from pyspark.sql.functions import udf


@udf("string")
def _clean(s):
    return s.replace(" ", "").upper()


def clean_postcodes(df: DataFrame) -> DataFrame:
    """Remove spaces from postcodes and upper-case them."""
    return df.withColumn("postcode", _clean("postcode"))

exercises.fix_solution:
from pyspark.sql import DataFrame
from pyspark.sql import functions as F


def clean_postcodes(df: DataFrame) -> DataFrame:
    """Remove spaces from postcodes and upper-case them. NULL stays NULL."""
    return df.withColumn("postcode", F.upper(F.regexp_replace(F.col("postcode"), r"\s+", "")))
